options.customCss:
/* TH-Koeln-Auftritt fuer die oeffentlichen Formulare.
   Gestaltung laeuft vollstaendig ueber CSS: Der Form Trigger filtert eigenes HTML,
   das CSS-Feld nicht. Das Logo steckt als Data-URI in einer Hintergrundregel. */
:root {
  --font-family: 'Source Sans 3', 'Source Sans Pro', -apple-system, 'Segoe UI', Roboto, sans-serif;
  --color-primary: #C81E0F;
  --color-primary-shade-1: #A81809;
  --color-secondary: #C81E0F;
  --color-submit-btn-bg: #C81E0F;
  --color-submit-btn-text: #FFFFFF;
  --color-button-primary-font: #FFFFFF;
  --color-header-label: #000000;
  --color-background: #FFFFFF;
  --color-card-bg: #FFFFFF;
  --color-input-border: #C8C8C8;
  --border-radius-card: 0px;
  --border-radius-input: 0px;
}

/* Heller Grund statt n8n-Grau, damit die Karte traegt */
body { background: #FFFFFF !important; }

/* Die Karte: Dreiklang-Streifen oben, Logo rechts, klare Kante statt Schatten */
.card, .form-container, [class*="formContainer"] {
  border: 1px solid #E4E4E4 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border-top: 5px solid #C81E0F !important;
  padding-top: 84px !important;
  position: relative !important;
  background-image: url("data:image/png;base64,") !important;
  background-repeat: no-repeat !important;
  background-position: right 24px top 22px !important;
  background-size: 92px auto !important;
}

/* Der Dreiklang als schmaler Streifen unter der roten Kante */
.card::before, .form-container::before {
  content: "";
  position: absolute; top: 0; left: 0; right: 0; height: 5px;
  /* Nur die drei Bereichsfarben: Technology, Arts, Sciences.
     Schwarz ist die Schriftfarbe der Wortmarke und gehoert nicht in den Streifen. */
  background: linear-gradient(to right,
    #C81E0F 0 33.34%, #EA5A00 33.34% 66.67%, #B43092 66.67% 100%);
}

/* Ueberschrift und Beschreibung */
h1 { letter-spacing: -0.01em !important; font-weight: 700 !important; color: #000 !important; }
h2, .description, [class*="description"] { color: #595959 !important; }

/* Beschriftungen: klein, gesperrt, wie die Kicker auf den Folien */
label, .form-label, [class*="label"] {
  font-weight: 600 !important;
  color: #000000 !important;
}

/* Eingabefelder: eckig, ruhig, roter Fokus */
input[type="text"], input[type="email"], input[type="number"], textarea, select,
.el-input__inner, .el-textarea__inner {
  border-radius: 0 !important;
  border-color: #C8C8C8 !important;
}
input:focus, textarea:focus, select:focus,
.el-input__inner:focus, .el-textarea__inner:focus {
  border-color: #C81E0F !important;
  box-shadow: 0 0 0 2px rgba(200, 30, 15, 0.15) !important;
  /* Ohne diese Zeile bleibt der Fokusring des Browsers sichtbar, in Chrome orange. */
  outline: 2px solid #C81E0F !important;
  outline-offset: 0 !important;
}

/* Absendeknopf. n8n benennt die Variablen je nach Fassung anders,
   deshalb hier die Selektoren direkt, das faengt alle Faelle ab. */
button[type="submit"], .btn--primary, .submit-button, input[type="submit"] {
  background-color: #C81E0F !important;
  border-color: #C81E0F !important;
  color: #FFFFFF !important;
  border-radius: 0 !important;
  font-weight: 600 !important;
  letter-spacing: 0.01em !important;
}
button[type="submit"]:hover, .btn--primary:hover, .submit-button:hover {
  background-color: #A81809 !important;
  border-color: #A81809 !important;
}

/* Pflichtfeld-Stern in Rot statt n8n-Orange */
.required, [class*="required"] { color: #C81E0F !important; }

/* Auf dem Telefon bleibt rechts Platz fuer das Logo */
@media (max-width: 520px) {
  .card, .form-container { background-size: 74px auto !important; padding-top: 72px !important; }
}

/* Erklärkästen zwischen den Feldern. n8n entfernt aus eigenem HTML class-Attribute und
   auch blockquote; Tabellen, Listen, pre, code und Überschriften bleiben (im Formular
   geprüft). Der Kasten ist deshalb eine einzellige Tabelle, die Typenliste darin eine
   verschachtelte Tabelle. Alles mit !important gegen die n8n-eigenen Regeln. */
table { width: 100% !important; border-collapse: separate !important; border-spacing: 0 !important;
  margin: 4px 0 20px !important; background: #F5F5F5 !important; border-left: 5px solid #C81E0F !important; }
table td { padding: 16px 18px 12px !important; font-size: 14.5px !important; line-height: 1.55 !important;
  color: #333333 !important; vertical-align: top !important; text-align: left !important; }
table table { margin: 10px 0 12px !important; background: #FFFFFF !important; border: 1px solid #DADADA !important; border-left: 1px solid #DADADA !important; }
table table td { padding: 7px 10px !important; border-bottom: 1px solid #E4E4E4 !important; font-size: 13.5px !important; line-height: 1.45 !important; }
table table tr:last-child td { border-bottom: 0 !important; }
table table td:first-child { width: 38% !important; white-space: nowrap !important; }
h3 { margin: 0 0 10px !important; font-size: 17px !important; font-weight: 700 !important; color: #000000 !important; line-height: 1.3 !important; }
td p { margin: 0 0 10px !important; font-size: 14.5px !important; line-height: 1.55 !important; color: #333333 !important; }
td ol { margin: 0 0 10px 20px !important; padding: 0 !important; }
td li { margin: 0 0 5px !important; font-size: 14.5px !important; line-height: 1.5 !important; }
td strong { color: #000000 !important; font-weight: 700 !important; }
td code { font-family: Menlo, Consolas, 'Courier New', monospace !important; font-size: 12.5px !important;
  background: #FFFFFF !important; border: 1px solid #C8C8C8 !important; border-radius: 3px !important;
  padding: 1px 6px !important; color: #C81E0F !important; white-space: nowrap !important; }
td pre { font-family: Menlo, Consolas, 'Courier New', monospace !important; font-size: 12.5px !important;
  background: #FFFFFF !important; border: 1px solid #DADADA !important; border-radius: 3px !important;
  padding: 10px 12px !important; margin: 8px 0 12px !important; white-space: pre-wrap !important;
  word-break: break-word !important; overflow-wrap: anywhere !important; line-height: 1.5 !important;
  color: #333333 !important; max-width: 100% !important; box-sizing: border-box !important; }
label { margin-top: 6px !important; }

parameters.jsCode:
// Der einzige Baustein mit Code. Er uebersetzt, was ein Mensch getippt hat,
// in das, was NocoDB versteht. Bedienende muessen hier nie hinein.
//
//   Fragen:  "tempo | Auswahl: zu langsam, genau richtig"  ->  Spalte mit Auswahlwerten
//   Nummern: beliebige Textwiese oder CSV                   ->  saubere Liste

const TYPEN = { text:'LongText', bewertung:'Rating', zahl:'Number', datum:'Date', janein:'Checkbox' };
const schluessel = s => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')
                        .replace(/[^a-z0-9_]/g,'_').replace(/^_+|_+$/g,'') || 'feld';
const c = $json;

// --- Fragen zu Spalten
const spalten = [];
for (const zeile of String(c.fragen).split('\n')) {
  const roh = zeile.trim();
  if (!roh) continue;
  const i = roh.indexOf('|');
  const name = (i < 0 ? roh : roh.slice(0, i)).trim();
  const art  = (i < 0 ? '' : roh.slice(i + 1)).trim();
  if (!name) continue;
  const klein = art.toLowerCase();
  if (klein.startsWith('auswahl')) {
    const werte = art.slice(art.indexOf(':') + 1).split(',').map(w => w.trim()).filter(Boolean);
    if (!werte.length) throw new Error(`Auswahl ohne Werte: "${roh}"`);
    spalten.push({ title: name, column_name: schluessel(name), uidt: 'SingleSelect',
                   dtxp: werte.map(w => `'${w.replace(/'/g, "''")}'`).join(',') });
  } else {
    spalten.push({ title: name, column_name: schluessel(name), uidt: TYPEN[klein] || 'SingleLineText' });
  }
}
if (!spalten.length) throw new Error('Keine Frage erkannt. Mindestens eine Zeile eintragen.');

// --- Matrikelnummern zu einer sauberen Liste
const gesehen = new Set();
const nummern = [];
for (const stueck of String(c.nummern || '').split(/[\n,;]+/)) {
  const n = stueck.trim().replace(/^["']|["']$/g, '');
  if (!/^[0-9]{3,20}$/.test(n)) continue;   // Kopfzeilen und Namen fliegen raus
  if (gesehen.has(n)) continue;             // Dubletten auch
  gesehen.add(n);
  nummern.push({ matrikelnummer: n });
}

const tabellenname = schluessel(c.titel);
const kennung = (tabellenname.slice(0, 28) + '-' + Math.random().toString(36).slice(2, 6)).replace(/_+/g, '-');
return [{ json: { ...c, spalten, nummern, anzahl_nummern: nummern.length, tabellenname, kennung } }];
